import React, { useReducer } from "react";
import PlaylistReducer from "./PlaylistReducer";

function PlaylistRed() {
  const [songs, dispatch] = useReducer(PlaylistReducer, []);

  return (
    <div>
      <h2>Playlist</h2>

      <button
        onClick={() =>
          dispatch({
            type: "ADD_SONG",
            payload: {
              id: 1,
              name: "Tum Hi Ho"
            }
          })
        }
      >
        Add Song
      </button>

      <button
        onClick={() =>
          dispatch({
            type: "REMOVE_SONG",
            payload: 1
          })
        }
      >
        Remove Song
      </button>

      {songs.map((song) => (
        <p key={song.id}>{song.name}</p>
      ))}
    </div>
  );
}

export default PlaylistCounter;
